/**
 * Odoo Node - Version 2
 * Discriminator: resource=custom, operation=get
 */


interface Credentials {
  odooApiKeyApi: CredentialReference;
  odooApi: CredentialReference;
}

/** Get an activity */
export type OdooV2CustomGetParams = {
  resource: 'custom';
  operation: 'get';
  authentication?: 'odooApiKeyApi' | 'odooApi' | Expression<string>;
/**
 * The Odoo model to operate on
 * @searchListMethod searchModels
 * @default {"mode":"list","value":""}
 */
    customResource?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Record to retrieve
 * @searchListMethod searchCustomRecords
 * @default {"mode":"list","value":""}
 */
    recordId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Options
 * @default {}
 */
    options?: {
    /** Comma-separated list of field names to include in the response
     */
    fieldsList?: string | Expression<string>;
  };
};

export type OdooV2CustomGetOutput = {
  id?: number;
  name?: string;
};

export type OdooV2CustomGetNode = {
  type: 'n8n-nodes-base.odoo';
  version: 2;
  config: NodeConfig<OdooV2CustomGetParams> & { credentials?: Credentials };
  output?: Items<OdooV2CustomGetOutput>;
};